    const payload: Record<string, unknown> = { ["totalAmount"]: { ["value"]: amountValue, ["currency"]: "PHP" }, ["requestReferenceNumber"]: trxId, ["redirectUrl"]: { ["success"]: redirectUrl, ["failure"]: cancelUrl, ["cancel"]: cancelUrl }, ["paymentMethod"]: "GCASH" };
